import {starter,additions,classes,fit,predict,evaluate,parseDataset,dataset} from './model.mjs';
const $=id=>document.getElementById(id),key='signal-garden-v1';
let rows=structuredClone(starter),model=null,step='train',storageOK=true;
function status(message){$('status').textContent=message;}
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved){rows=parseDataset(JSON.stringify(saved.data));if([1,3,5].includes(saved.k))$('neighbors').value=String(saved.k);if(typeof saved.reflection==='string')$('reflection').value=saved.reflection.slice(0,2000);}}catch{storageOK=false;status('Saved data could not be read. A fresh experiment is ready; imports and exports still work.');}
function persist(){try{localStorage.setItem(key,JSON.stringify({data:dataset(rows),k:Number($('neighbors').value),reflection:$('reflection').value}));}catch{storageOK=false;status('Browser storage is unavailable or full. Your current experiment works; export to keep a copy.');}}
function svg(tag,attrs={},content){const el=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))el.setAttribute(k,String(v));if(content!==undefined)el.textContent=content;return el;}
const color=label=>label===0?'#d89b3c':'#45877f',point=(p)=>[25+p.x*750,365-p.y*340];
function draw(){const root=svg('svg',{viewBox:'0 0 800 390',role:'img','aria-label':model?'Fitted nearest-neighbor decision map, with labeled examples and the query':'Training examples before fitting'});const add=(tag,attrs,text)=>root.append(svg(tag,attrs,text));
 if(model)for(let x=0;x<30;x++)for(let y=0;y<18;y++){const q=predict(model.rows,(x+.5)/30,(y+.5)/18,model.k);add('rect',{x:25+x*25,y:25+y*340/18,width:25.1,height:340/18+.1,fill:color(q.label),opacity:.11});}
 for(let i=0;i<=10;i++){const x=25+i*75,y=25+i*34;add('line',{x1:x,y1:25,x2:x,y2:365,stroke:'#d9ddce','stroke-width':.5});add('line',{x1:25,y1:y,x2:775,y2:y,stroke:'#d9ddce','stroke-width':.5});}
 add('text',{x:28,y:16,fill:'#657368','font-size':10,'font-family':'monospace'},'STEM HEIGHT ↑');
 const qx=Number($('queryX').value)/100,qy=Number($('queryY').value)/100;
 if(model){const pred=predict(model.rows,qx,qy,model.k);for(const p of pred.neighbors){const [x,y]=point(p),[xx,yy]=point({x:qx,y:qy});add('line',{x1:x,y1:y,x2:xx,y2:yy,stroke:'#304b3b','stroke-width':1,'stroke-dasharray':'4 5',opacity:.6});}}
 rows.forEach((p,i)=>{const[x,y]=point(p);const el=svg('circle',{cx:x,cy:y,r:6,fill:color(p.label),stroke:'#fffef9','stroke-width':2});el.append(svg('title',{},`Training ${i+1}: ${classes[p.label]}, width ${Math.round(p.x*100)}, height ${Math.round(p.y*100)}`));root.append(el);});
 if(step!=='train')for(const p of (model?evaluate(model).results:[])){const[x,y]=point(p);const el=svg('path',{d:`M${x} ${y-5}l5 5 -5 5 -5 -5Z`,fill:p.correct?'#fffef9':'#c26644',stroke:p.correct?color(p.label):'#994d31','stroke-width':1.5});el.append(svg('title',{},`Held-out: actual ${classes[p.label]}, predicted ${classes[p.predicted]}, ${p.correct?'correct':'incorrect'}`));root.append(el);}
 const[x,y]=point({x:qx,y:qy});add('circle',{cx:x,cy:y,r:11,fill:'none',stroke:'#203c32','stroke-width':2});add('line',{x1:x-16,y1:y,x2:x+16,y2:y,stroke:'#203c32','stroke-width':1});add('line',{x1:x,y1:y-16,x2:x,y2:y+16,stroke:'#203c32','stroke-width':1});
 $('plot').replaceChildren(root);
}
function prediction(){const target=$('prediction');target.replaceChildren();if(!model){target.textContent='Fit a model first.';return;}const result=predict(model.rows,Number($('queryX').value)/100,Number($('queryY').value)/100,model.k);const strong=document.createElement('strong');strong.textContent=classes[result.label];strong.style.color=color(result.label);target.append(strong,document.createTextNode(`${Math.round(result.share*100)}% neighbor agreement (${Math.round(result.share*model.k)} of ${model.k}). ${result.far?'Far from known evidence. ':''}Vote share, not probability.`));}
function matrix(result){const root=$('matrix');root.replaceChildren();['Actual ↓ / Predicted →','Sun','Shade','Sun',result.matrix[0][0],result.matrix[0][1],'Shade',result.matrix[1][0],result.matrix[1][1]].forEach((v,i)=>{const el=document.createElement('div');el.textContent=String(v);if([4,8].includes(i))el.className='good';if([5,7].includes(i))el.className='bad';root.append(el);});}
function render(){
 $('rowCount').textContent=String(rows.length);$('repair').disabled=additions.every(a=>rows.some(p=>p.x===a.x&&p.y===a.y&&p.label===a.label));$('coverage').textContent=$('repair').disabled?'Missing corners added. Fit again, then inspect the test results.':'Add 12 synthetic examples from the two missing corners.';
 $('plotHint').textContent=model?'Tint = prediction region · dashed lines = nearest neighbors':'Fit the model to reveal its decision regions.';
 $('testDetails').hidden=step==='train'||!model;
 for(const b of document.querySelectorAll('[data-tab]')){b.classList.toggle('active',b.dataset.tab===step);if(b.dataset.tab===step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');}
 const messages={train:['Start with what you know.','Our first eight examples cover two small corners. Will the model understand the rest of the garden?'],test:['Look beyond the practice score.','The diamonds are separate test examples. Filled rust diamonds show where the model made a mistake.'],improve:['Change the evidence. Not the story.','Add examples from the missing corners, refit, then compare. What can this small test actually tell us?']};
 $('stepTitle').textContent=messages[step][0];$('stepHelp').textContent=messages[step][1];
 if(model){const training=evaluate(model,model.rows),testing=evaluate(model);$('trainScore').textContent=Math.round(training.correct/training.total*100)+'%';$('testScore').textContent=Math.round(testing.correct/testing.total*100)+'%';$('testNote').textContent=`${testing.correct} of ${testing.total} correct · fixed synthetic set`;
 const improved=testing.correct===testing.total;$('insightTitle').textContent=improved?'Better coverage. Better evidence.':'A perfect practice score can mislead.';$('insightText').textContent=improved?'This model gets all 16 designed examples right. That supports this exercise, not a real-world accuracy claim. Try a new example or export your findings.':`The model misses ${testing.total-testing.correct} of 16 held-out examples. Inspect the missing corners before changing settings. The training score includes familiar examples.`;matrix(testing);
 }else{$('trainScore').textContent='—';$('testScore').textContent='—';$('testNote').textContent='Fit the current examples to evaluate them.';$('insightTitle').textContent='Confidence can hide a blind spot.';$('insightText').textContent='A unanimous neighbor vote can still be wrong. Compare the familiar training examples with the separate test set.';}
 $('exportReport').disabled=!model;draw();prediction();
}
function changed(message){model=null;persist();render();status(message+(storageOK?'':' Export your examples to keep a copy.'));}
for(const b of document.querySelectorAll('[data-tab]'))b.addEventListener('click',()=>{step=b.dataset.tab;render();status(model?'Explore the map, inspect the held-out evidence, and record what you notice.':'Fit a model to inspect predictions and test results.');});
$('fit').addEventListener('click',()=>{try{model=fit(rows,Number($('neighbors').value));render();status(`Fitted k-nearest neighbors with ${model.rows.length} examples and k = ${model.k}. No network request was made.`);persist();}catch(error){status(error.message);}});
$('repair').addEventListener('click',()=>{const missing=additions.filter(a=>!rows.some(p=>p.x===a.x&&p.y===a.y&&p.label===a.label));if(rows.length+missing.length>500){status('The 500-example limit would be exceeded. Export or reset first.');return;}rows=[...rows,...structuredClone(missing)];step='improve';changed(`Added ${missing.length} examples from underrepresented corners. Fit again to measure the change.`);});
$('neighbors').addEventListener('change',()=>changed('Settings changed. Fit again before using these results.'));
for(const prefix of ['query','add'])for(const axis of ['X','Y'])$(prefix+axis).addEventListener('input',()=>{$(prefix+axis+'out').textContent=$(prefix+axis).value;if(prefix==='query'){draw();prediction();}});
$('add').addEventListener('click',()=>{if(rows.length>=500){status('The 500-example limit is reached. Export or reset first.');return;}rows.push({x:Number($('addX').value)/100,y:Number($('addY').value)/100,label:Number($('addLabel').value)});changed('Your labeled example was added. Fit again to see its effect.');});
$('reset').addEventListener('click',()=>{rows=structuredClone(starter);$('neighbors').value='3';step='train';changed('Starter examples restored. Your reflection was preserved. Fit to begin again.');});
$('reflection').addEventListener('input',persist);
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('exportData').addEventListener('click',()=>{download('signal-garden-dataset.json',dataset(rows));status('Dataset exported. No data was uploaded.');});
$('exportReport').addEventListener('click',()=>{if(!model){status('Fit a model before exporting a report.');return;}download('signal-garden-report.json',{kind:'signal-garden-report',version:1,created:new Date().toISOString(),method:'k-nearest neighbors, Euclidean distance, majority vote',k:model.k,dataset:dataset(model.rows),training:evaluate(model,model.rows),heldOut:evaluate(model),reflection:$('reflection').value,limitations:['Synthetic teaching exercise; no real botanical data.','Training score includes each query itself among neighbors.','The fixed test set becomes development evidence after inspection; real validation needs new untouched data.','Neighbor agreement is not a calibrated probability.']});status('Lab report exported with the fitted examples, test evidence and your reflection.');});
$('importData').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error('Import a JSON file under 100 KB.');const next=parseDataset(await file.text());rows=next;step='train';changed(`Imported ${rows.length} validated examples. Fit to start a new experiment.`);}catch(error){status('Import rejected: '+error.message+' Your current experiment was preserved.');}finally{e.target.value='';}});
render();
